  $slsmjson${"slug": "sales-management", "title": "Sales Management", "description": "Define the role of sales management in go-to-market strategy, revenue growth, and customer value creation.", "topics": [{"id": "128a0c3d-d988-4b5f-93d6-cee667df142e", "type": "topic", "title": "Sales Management Strategy and the Revenue Organization", "description": "Define the role of sales management in go-to-market strategy, revenue growth, and customer value creation.", "children": [{"id": "a24a59fd-8462-4eae-9554-c1d3991ab038", "type": "subtopic", "title": "Sales as part of go-to-market strategy", "children": [{"id": "a11d7749-34f6-4f47-bfbe-3d29410fa589", "type": "concept", "title": "Go-to-market motions: inbound, outbound, product-led, channel-led, and enterprise sales"}, {"id": "3193988a-1db6-4a90-9915-104fbf3ebc9b", "type": "concept", "title": "Market selection, customer segments, and value propositions"}, {"id": "41ceeee4-df38-4584-8adb-11a14743ec09", "type": "concept", "title": "Sales and marketing alignment"}, {"id": "572edddf-59c9-48f7-a94d-83c0c854f628", "type": "concept", "title": "Revenue growth, margin, retention, and customer lifetime value"}], "description": "Students learn how sales fits with marketing, product, customer success, finance, and operations. The point is to manage sales as a strategic revenue system rather than a stand-alone quota machine."}, {"id": "8478550a-9602-4cf9-a632-2ca01cca2c48", "type": "subtopic", "title": "Revenue organization design", "children": [{"id": "bb3e59d5-7906-4311-a1c5-c1250ba2c9bc", "type": "concept", "title": "Sales, marketing, revenue operations, enablement, customer success, and support"}, {"id": "ca4a6b83-7ea4-4a70-8d18-01cb1ee2c1f0", "type": "concept", "title": "Acquisition, expansion, renewal, and retention responsibilities"}, {"id": "19322ee0-2c60-4f5b-ab25-82fa1e500782", "type": "concept", "title": "Hand-offs and service-level agreements"}, {"id": "59afdb15-a5cf-4648-b37c-31a630c741fa", "type": "concept", "title": "Common friction points across revenue teams"}], "description": "This subtopic introduces the modern revenue organization and clarifies how different teams share accountability for growth."}, {"id": "712cb2d3-228e-4c38-8077-9b817b1e434f", "type": "subtopic", "title": "Sales management decision rights", "children": [{"id": "100f73cb-a6af-425c-a6ae-f01a39202759", "type": "concept", "title": "Operating rhythms and inspection cadence"}, {"id": "c59e1df6-2b63-4f7b-91ef-628508c3373f", "type": "concept", "title": "Manager versus rep responsibilities"}, {"id": "54ac709f-b08d-4145-ab8b-e5c82932928c", "type": "concept", "title": "Short-term target pressure versus long-term customer trust"}, {"id": "13c748a8-dff5-4607-80f0-9d86dc52779f", "type": "concept", "title": "Governance of exceptions, discounts, and escalations"}], "description": "Sales managers make repeated choices about people, accounts, process, pricing, and performance. Students learn what decisions managers own and what evidence should guide them."}]}, {"id": "0c5b6f4f-9244-46d6-995b-8fc4bc1c2685", "type": "topic", "title": "Buyer Behavior, Customer Value, and Consultative Selling", "description": "Connect consumer and organizational buying behavior to relationship-centered sales practice.", "children": [{"id": "d18a31de-8364-4a70-86ec-f07862c019c5", "type": "subtopic", "title": "Buyer decision processes", "children": [{"id": "dda5afc9-b411-43b3-aa61-36bc56ceb42e", "type": "concept", "title": "Consumer and organizational buying centers"}, {"id": "4a82dcac-5c0f-44bc-8a4e-aa8cddc96451", "type": "concept", "title": "Needs, triggers, constraints, and switching costs"}, {"id": "3d24b778-00b9-487e-a54c-ce6af5c2e9aa", "type": "concept", "title": "Rational, emotional, social, and political drivers"}, {"id": "49b8095a-cf42-44ae-bf1b-a6492e3a3322", "type": "concept", "title": "Post-purchase behavior and trust formation"}], "description": "Sales teams perform better when they understand how buyers perceive risk, evaluate alternatives, and build internal consensus."}, {"id": "a1ede90f-2c03-4c6e-9a93-033fd7f992d2", "type": "subtopic", "title": "Consultative and value-based selling", "children": [{"id": "65a4a3b2-e197-44ec-b61c-5cf23c25cbe0", "type": "concept", "title": "Discovery questions and active listening"}, {"id": "6a199003-f911-4ce0-86d0-3bd69401c502", "type": "concept", "title": "Pain, impact, desired state, and decision criteria"}, {"id": "33898850-e5fa-4b18-b2c4-73f4d83d4176", "type": "concept", "title": "Value hypotheses and business cases"}, {"id": "6d83f4c2-3fc6-4056-ae98-1f183c064879", "type": "concept", "title": "Teaching insight without becoming pushy"}], "description": "This subtopic shifts selling from pitching products to diagnosing problems and building value cases."}, {"id": "e0ed06de-c5fd-4295-a492-611abc9305bb", "type": "subtopic", "title": "Customer value and segmentation", "children": [{"id": "ec9afc27-6763-4399-9082-e9bb5fed2391", "type": "concept", "title": "CLV, willingness to pay, strategic fit, and account potential"}, {"id": "3b0382c4-6674-4bf3-b58f-0bbcac3e4248", "type": "concept", "title": "Segmenting by industry, use case, size, and maturity"}, {"id": "160f07cf-58c2-4050-9f27-85a4ac2b3585", "type": "concept", "title": "Customer profitability and cost-to-serve"}, {"id": "8c11d87b-5c81-40cd-b820-a68063f012c2", "type": "concept", "title": "Ethical limits of prioritization"}], "description": "Not every customer should receive the same sales effort. Students learn to link sales coverage to potential value."}]}, {"id": "5dd1b67a-767d-4658-8320-6cc1139cb874", "type": "topic", "title": "Sales Force Design, Roles, and Structure", "description": "Design sales roles, coverage models, reporting lines, and specialization choices for different markets.", "children": [{"id": "73e52143-496a-40f1-8194-365bc2a60219", "type": "subtopic", "title": "Sales role specialization", "children": [{"id": "b5d6e477-4966-4405-845d-4967f8d14e40", "type": "concept", "title": "SDR/BDR, account executive, account manager, sales engineer, channel manager, and customer success roles"}, {"id": "a88ee366-627b-4801-88c9-65956e5d5709", "type": "concept", "title": "Hunters, farmers, and hybrid roles"}, {"id": "5e9ebecf-5b43-436e-94e2-6cc0e79ba660", "type": "concept", "title": "Inside, field, enterprise, and transactional sales"}, {"id": "d9cf42ef-9096-4349-af6c-a82f8e6483a2", "type": "concept", "title": "Role clarity and handoff risks"}], "description": "Students learn how role design affects productivity, accountability, and customer experience."}, {"id": "12c7f6e1-9675-4e95-821c-d7e303a11598", "type": "subtopic", "title": "Organizational structure choices", "children": [{"id": "db27219f-905f-42f5-8627-fb046ee34b82", "type": "concept", "title": "Geographic, product, market, industry, and named-account structures"}, {"id": "db29569a-aefd-41e8-97c0-791938991943", "type": "concept", "title": "Matrixed sales organizations"}, {"id": "e2c5d609-dd2d-4705-a2da-b2f7c161a4b9", "type": "concept", "title": "Channel partners and indirect sales"}, {"id": "7656a2c2-fbfc-44fb-8a15-61ce0300803b", "type": "concept", "title": "Span of control and manager workload"}], "description": "This subtopic covers the ways sales teams can be organized around customers, products, geography, and channels."}, {"id": "9254f976-9d2e-4fbb-b862-25c4fd0850af", "type": "subtopic", "title": "Coverage model economics", "children": [{"id": "c58dd266-5b45-4d59-9f21-1ad16d4b55c5", "type": "concept", "title": "High-touch versus low-touch coverage"}, {"id": "7f701265-df50-4712-8f88-d9491ebb361f", "type": "concept", "title": "Enterprise versus SMB economics"}, {"id": "1779eaef-bfac-4eb8-ad1a-dc2f6ef1a4ec", "type": "concept", "title": "Customer acquisition cost and payback period"}, {"id": "a0f55dbc-3598-46a2-b2f3-c506410019a7", "type": "concept", "title": "Coverage gaps, overlaps, and conflict"}], "description": "Sales structure should match opportunity value and buying complexity. Students learn to think through cost-to-sell."}]}, {"id": "90f9f11a-7cf3-404f-934f-640705258d12", "type": "topic", "title": "Prospecting, Lead Management, and Pipeline Development", "description": "Build a disciplined prospecting system from targeting through qualified opportunity creation.", "children": [{"id": "2ebedc87-1d6b-4874-bfd8-08d1e1223a7d", "type": "subtopic", "title": "Targeting and ideal customer profiles", "children": [{"id": "e8bb42ad-97e6-4e2e-8c26-c3d164adc9fa", "type": "concept", "title": "Ideal customer profile criteria"}, {"id": "53d8af9a-0bf4-4708-878d-0e62d653d8d8", "type": "concept", "title": "Total addressable market, serviceable market, and account lists"}, {"id": "c825d650-47c2-4df5-b973-24aa473826ca", "type": "concept", "title": "Trigger events and buying signals"}, {"id": "cbb1dfd0-a42d-4131-ada7-e7cce59dff39", "type": "concept", "title": "Data quality and account research"}], "description": "Good prospecting begins with focus. Students learn to define who is worth pursuing and why."}, {"id": "03f5b47b-68f3-486b-8c71-4e3461dfa031", "type": "subtopic", "title": "Lead generation and qualification", "children": [{"id": "9fdac8e8-af69-4296-ac05-2d2550bb03b1", "type": "concept", "title": "Inbound, outbound, referral, event, and partner sources"}, {"id": "165ba1d5-1110-400b-b4f6-f85a2157fab0", "type": "concept", "title": "MQL, SQL, SAL, and opportunity definitions"}, {"id": "a0a6db1a-daa5-454e-b6fe-26f101cfd026", "type": "concept", "title": "BANT, MEDDIC, SPICED, and other qualification frameworks"}, {"id": "1007b0d7-03d0-442d-b518-960d77e4c395", "type": "concept", "title": "Lead scoring and routing"}], "description": "This subtopic teaches how leads become qualified opportunities through disciplined criteria and timing."}, {"id": "f76dfb18-2075-4a51-b373-d5ab749ec7c4", "type": "subtopic", "title": "Pipeline creation and prospecting cadence", "children": [{"id": "11b7c5c8-e687-4971-b20c-3da69706e193", "type": "concept", "title": "Email, phone, social, and video outreach"}, {"id": "e1cb4220-95c7-49ea-850d-ffb69b7e0925", "type": "concept", "title": "Cadences, sequences, and personalization"}, {"id": "e3b4243a-7668-4113-8938-494d6c7a3f93", "type": "concept", "title": "Pipeline coverage ratios"}, {"id": "266c00d1-cd74-4660-afb8-21571fe414f4", "type": "concept", "title": "Prospecting ethics and anti-spam compliance"}], "description": "Students learn practical systems for outreach, follow-up, and pipeline coverage."}]}, {"id": "a7927901-1d9c-477e-a09f-1b2c5674ce3a", "type": "topic", "title": "Personal Selling Process and Sales Conversation Skills", "description": "Practice needs discovery, presentations, objection handling, closing, and follow-up.", "children": [{"id": "aee6b7f9-9fb0-4e47-b4d3-e04882c1d10c", "type": "subtopic", "title": "Discovery and diagnosis", "children": [{"id": "03635cab-2fe4-4b46-952e-5e18897db2d7", "type": "concept", "title": "Open-ended questioning"}, {"id": "6219f74b-3877-437c-9537-00f3f073845c", "type": "concept", "title": "Active listening and summarizing"}, {"id": "567fd807-b9b4-473a-ae5d-f522cd2947b0", "type": "concept", "title": "Problem, impact, and urgency"}, {"id": "b1776761-7965-4a0d-8b31-6abc60879057", "type": "concept", "title": "Stakeholder mapping and decision criteria"}], "description": "Discovery is the foundation of credible selling. Students practice uncovering needs, constraints, decision processes, and value drivers."}, {"id": "8901e829-e98c-4bf0-b417-e411b8d8d0ec", "type": "subtopic", "title": "Presentations and proposals", "children": [{"id": "b6bcdd88-3ff9-45d5-839f-843189551c73", "type": "concept", "title": "Tailored demos and storytelling"}, {"id": "acdad69b-fabe-4f2f-8fa2-a255b9f8fd29", "type": "concept", "title": "Features, benefits, and proof"}, {"id": "973d7ef6-db10-48ec-b217-42acfe189e68", "type": "concept", "title": "Proposal structure and executive summaries"}, {"id": "edf7d0cc-a11b-4fee-bace-0d435e0d1a64", "type": "concept", "title": "ROI, risk reduction, and implementation plans"}], "description": "This subtopic covers how to connect the solution to the customer's stated problem and desired outcome."}, {"id": "524c06f9-42fd-462d-b8d7-01d376a5c7d4", "type": "subtopic", "title": "Objections, closing, and follow-up", "children": [{"id": "f1acc38c-db8c-4805-bc49-b1b89f2ec35f", "type": "concept", "title": "Objection diagnosis versus rebuttal scripts"}, {"id": "01e79ab2-5c7e-4379-9fb7-c7282f758152", "type": "concept", "title": "Timing, authority, budget, and risk concerns"}, {"id": "89bdef4d-3649-4006-8b9f-6d81c41dc5f3", "type": "concept", "title": "Trial closes and mutual action plans"}, {"id": "293fc6b5-6fdc-49d2-9765-24c29639c6b0", "type": "concept", "title": "Post-meeting follow-up and commitment tracking"}], "description": "Students learn to handle concerns professionally and guide customers toward clear next steps."}]}, {"id": "57391dc3-654a-43c0-915f-36716a2aa2b6", "type": "topic", "title": "Sales Negotiation, Influence, and Deal Strategy", "description": "Use preparation, BATNA analysis, value creation, and ethical influence in sales negotiations.", "children": [{"id": "6b6d3c01-1712-43c4-918d-d97114935fda", "type": "subtopic", "title": "Negotiation preparation", "children": [{"id": "9b023e54-c81f-4479-a9bf-ae5a4de93e9b", "type": "concept", "title": "BATNA, reservation value, aspiration point, and walk-away rules"}, {"id": "05e82f94-b0fb-4c26-ad33-8912caa28c8d", "type": "concept", "title": "Stakeholder interests and constraints"}, {"id": "bf82fa16-dafb-4209-927f-c912fb0c4112", "type": "concept", "title": "Concession planning"}, {"id": "ab97f2c0-a2f6-4ec6-93f2-c764c088be55", "type": "concept", "title": "Issue lists and tradeable variables"}], "description": "Preparation protects both value and relationships. Students learn to define targets before entering a deal conversation."}, {"id": "41f7dc8c-bc2f-4583-94f0-6c916eb03a4b", "type": "subtopic", "title": "Value creation and value claiming", "children": [{"id": "15e9f303-6c8f-484e-bfa8-302ad1ce3e67", "type": "concept", "title": "Distributive versus integrative bargaining"}, {"id": "d009f73c-7db6-4698-b14d-a9ce8608a59d", "type": "concept", "title": "Logrolling and package deals"}, {"id": "5ab6b8a2-b905-4835-9b45-0b20b36055d7", "type": "concept", "title": "Price, scope, timing, service levels, and contract terms"}, {"id": "ae022b59-ba9e-45bd-842c-da150c5d34fa", "type": "concept", "title": "Anchoring, framing, and information sharing"}], "description": "This subtopic teaches students to look for mutual gains while still protecting business outcomes."}, {"id": "68a6b8a1-a979-4b6c-8a47-e6e13aabac9a", "type": "subtopic", "title": "Difficult tactics and ethical influence", "children": [{"id": "f1e256a2-9626-4c8f-9506-6bce4f5fdfb8", "type": "concept", "title": "Power asymmetry and procurement pressure"}, {"id": "dd12f8fd-dd26-4e6e-8321-400fba93a553", "type": "concept", "title": "Emotion, silence, deadlines, and escalation"}, {"id": "5a1f9b15-7506-4da9-98f4-ed83fee72371", "type": "concept", "title": "Deception, bluffing, and reputation"}, {"id": "741c2ec8-124b-4467-8387-baff65152c5a", "type": "concept", "title": "Cross-cultural and team negotiations"}], "description": "Sales negotiation requires judgment under pressure. Students learn to respond to hardball tactics without sacrificing trust."}]}, {"id": "6968798d-0176-4ff8-96a6-cab9a820d903", "type": "topic", "title": "Recruiting, Selection, Onboarding, and Sales Training", "description": "Build a hiring and training system that improves capability, ramp time, and retention.", "children": [{"id": "2d40ab86-2eb2-47f7-a0b4-41e7c4e8debf", "type": "subtopic", "title": "Sales talent profiles", "children": [{"id": "b088aa17-a535-4f89-a1dc-07cdbfb023c0", "type": "concept", "title": "Competency models"}, {"id": "0239a8d4-bbe5-4934-9c74-12ca6851b5dd", "type": "concept", "title": "Coachability, resilience, curiosity, discipline, and business acumen"}, {"id": "155ddee8-d1b5-42c1-b0ae-91ff02512ed7", "type": "concept", "title": "Role-specific skills for SDRs, AEs, account managers, and sales engineers"}, {"id": "7d4edb48-b4a4-4b17-b61d-bc7c7dce53c6", "type": "concept", "title": "Structured interviews and work samples"}], "description": "Students learn what capabilities different sales roles require and why hiring for generic charisma is not enough."}, {"id": "8e441267-07ba-4be5-8383-58bd511cd1ec", "type": "subtopic", "title": "Selection and onboarding systems", "children": [{"id": "55a14c37-b8ec-4a83-8906-8756b813fb9d", "type": "concept", "title": "Job scorecards and realistic job previews"}, {"id": "54564450-e891-4b13-8e13-d0cd61f4869f", "type": "concept", "title": "Assessment tasks and reference checks"}, {"id": "313bef0d-6601-4c20-aff2-a39e9d8a36ad", "type": "concept", "title": "Onboarding milestones"}, {"id": "a3898802-2fea-4e90-84f1-58121e8a0d93", "type": "concept", "title": "Ramp metrics and early warning signs"}], "description": "This subtopic covers how to reduce hiring bias and accelerate ramp time."}, {"id": "c2f94499-3b12-4b85-8152-48235ed2e376", "type": "subtopic", "title": "Training and enablement", "children": [{"id": "2980ac75-d19f-494b-8ef4-7b95fdddb454", "type": "concept", "title": "Product, market, process, methodology, and tool training"}, {"id": "67c66a22-9ff5-458d-87a7-5dc8cfa7f05c", "type": "concept", "title": "Role plays and call reviews"}, {"id": "223a7b52-59e2-43e6-a3dc-be88ce958c2c", "type": "concept", "title": "Playbooks and certification"}, {"id": "5b029a08-5b36-4a91-ae15-5682f16d4dc1", "type": "concept", "title": "Reinforcement, coaching, and continuous learning"}], "description": "Sales training should improve behavior in the field. Students learn how to design practical learning systems."}]}, {"id": "bdd0576f-9fd8-4e0b-959f-4b57017cd107", "type": "topic", "title": "Motivation, Coaching, Leadership, and Sales Culture", "description": "Lead sales teams through coaching, feedback, incentives, culture, and performance conversations.", "children": [{"id": "59bcfeff-2372-4386-813d-fbd1d3c27007", "type": "subtopic", "title": "Sales motivation", "children": [{"id": "d29a2cf4-c115-41a8-82f8-f63835cd1367", "type": "concept", "title": "Intrinsic and extrinsic motivation"}, {"id": "c40179fd-92b5-4ab7-b00f-3e810b149f60", "type": "concept", "title": "Goal setting and expectancy theory"}, {"id": "b6842425-a04c-405b-ae96-74ac9d231916", "type": "concept", "title": "Recognition and contests"}, {"id": "f5fb3c3d-264b-486d-9e24-d54cb44fecb0", "type": "concept", "title": "Burnout, pressure, and sustainable performance"}], "description": "Motivation is not only about money. Students learn how goals, recognition, autonomy, purpose, and fairness shape performance."}, {"id": "2cba5e73-87fd-45af-8380-799a43f29f2d", "type": "subtopic", "title": "Coaching and performance conversations", "children": [{"id": "29cb2bb8-0c24-4368-a171-dd9c9d3c49bc", "type": "concept", "title": "One-on-ones and field coaching"}, {"id": "13ac7d1d-10b1-414f-9080-b20041fb4ebf", "type": "concept", "title": "Call review and deal review"}, {"id": "4f88f35b-f0a8-4f6c-a3b0-892074101941", "type": "concept", "title": "Feedback models and behavior change"}, {"id": "dcad0c39-393e-4e00-9897-018033dba2eb", "type": "concept", "title": "Coaching plans and accountability"}], "description": "This subtopic teaches managers to improve rep capability through observation, feedback, and practice."}, {"id": "f75083a3-3d62-4bef-bf70-9d61b7a27ee1", "type": "subtopic", "title": "Sales culture and leadership", "children": [{"id": "7f6c150f-4805-43ae-9939-6b585e85fa84", "type": "concept", "title": "Psychological safety and accountability"}, {"id": "cc479524-5f4d-4197-9775-b6f34eb24dd7", "type": "concept", "title": "Competitive versus collaborative norms"}, {"id": "d4896978-cdeb-41a3-984d-9001dbf6c194", "type": "concept", "title": "Learning culture and experimentation"}, {"id": "1cd745c0-1908-4bb0-a890-78f5ee1d30ca", "type": "concept", "title": "Manager role modeling"}], "description": "Sales culture affects ethics, collaboration, turnover, and customer experience. Students learn to diagnose and shape it."}]}, {"id": "798aba56-404b-448b-80f2-903ff9207dc6", "type": "topic", "title": "Compensation, Quotas, and Incentive Design", "description": "Align compensation plans, quotas, and rewards with strategy, fairness, and profitable growth.", "children": [{"id": "5861e9af-96e3-4337-a0f2-34be9d0e5e27", "type": "subtopic", "title": "Compensation plan architecture", "children": [{"id": "f7577132-38d4-44d3-bb1d-9ef9c1bf2267", "type": "concept", "title": "Base salary, commission, bonus, accelerators, and thresholds"}, {"id": "6caa18ea-6369-4dba-96be-8e6f43d81da3", "type": "concept", "title": "OTE and pay mix"}, {"id": "8e1a5d13-45fd-46fe-9d9b-99a982565feb", "type": "concept", "title": "Individual versus team incentives"}, {"id": "a249e690-29ea-45f1-84f8-f71b81ca34c8", "type": "concept", "title": "Caps, cliffs, and unintended consequences"}], "description": "Students learn how pay design influences behavior and how misaligned incentives can create problems."}, {"id": "da0329da-6f86-402b-90ce-869c77daeeb9", "type": "subtopic", "title": "Quota setting", "children": [{"id": "b01d3e12-0533-4043-8fd5-c8227800b74d", "type": "concept", "title": "Top-down and bottom-up quotas"}, {"id": "ab79a791-baea-4fe5-a990-8767d2d419ae", "type": "concept", "title": "Territory potential and historical performance"}, {"id": "99ae708a-8437-4535-9386-f0d78853b8a0", "type": "concept", "title": "Seasonality and market change"}, {"id": "ac7cb1f8-f0da-4971-8ea6-29d490208987", "type": "concept", "title": "Quota relief and exceptional events"}], "description": "Quota quality affects fairness and performance. This subtopic covers methods for building credible targets."}, {"id": "5dba136b-5533-4364-aa25-b206aad12b8f", "type": "subtopic", "title": "Incentive ethics and governance", "children": [{"id": "7d52222e-4db7-4d9d-ae7f-f4be126f6ac3", "type": "concept", "title": "Gaming, sandbagging, and channel stuffing"}, {"id": "382653e1-46ed-42d2-aca3-d4f9ae47adbd", "type": "concept", "title": "Discount behavior and margin protection"}, {"id": "6d18f8d1-f78f-41a8-9a6d-78283124da46", "type": "concept", "title": "Clawbacks and disputes"}, {"id": "cea73441-bed0-470a-aa12-b5eaf454c408", "type": "concept", "title": "Transparent plan communication"}], "description": "Students learn to design incentives that support customer trust, compliance, and long-term growth."}]}, {"id": "e87dd646-3d8c-46d4-9fec-abcf8fd65313", "type": "topic", "title": "Territory Design, Account Allocation, and Coverage Planning", "description": "Allocate sales effort across territories, accounts, channels, and market opportunities.", "children": [{"id": "067aca16-5484-4a88-aed1-9c167607f786", "type": "subtopic", "title": "Territory design principles", "children": [{"id": "a70853ef-8678-45bb-8341-9fe2f0aa10e5", "type": "concept", "title": "Geography, industry, account size, and potential"}, {"id": "f41425e1-492e-4b0e-a491-9ea8caab73d6", "type": "concept", "title": "Workload, travel time, and account density"}, {"id": "717a16fd-a579-4aaa-b287-294ce656e8e4", "type": "concept", "title": "Named accounts versus open territories"}, {"id": "e9fe7ba2-0580-413a-a56c-ff62c72b004a", "type": "concept", "title": "Territory realignment and disruption"}], "description": "Territory design determines opportunity access and workload balance. Students learn basic methods for fair and productive allocation."}, {"id": "9f400836-d8f3-4940-8d8e-027ae6b2ec54", "type": "subtopic", "title": "Account prioritization", "children": [{"id": "b87239b0-5298-45d2-b7f6-e2cef488fa1d", "type": "concept", "title": "A/B/C account tiers"}, {"id": "12795a01-1f6a-43b9-9029-447892c9763d", "type": "concept", "title": "Whitespace analysis"}, {"id": "977ff163-594e-4f3e-b679-c7daaf35c314", "type": "concept", "title": "Propensity and intent signals"}, {"id": "4c1bffc0-1ee6-4f57-b4d9-261d1ed5e59f", "type": "concept", "title": "Account plans and mutual action plans"}], "description": "This subtopic teaches students to allocate effort based on potential, fit, and strategic value."}, {"id": "63f6991e-1331-415d-b021-0794a015e4fa", "type": "subtopic", "title": "Channel and partner coverage", "children": [{"id": "8a08edaa-476c-4c32-bed6-d06eb2c7abc5", "type": "concept", "title": "Direct versus indirect channel choices"}, {"id": "f0b380ba-b9ab-4307-aa79-5fb7e056cb34", "type": "concept", "title": "Partner selection and enablement"}, {"id": "b3c0b878-c5d8-4e37-837f-9e7f531741a1", "type": "concept", "title": "Channel conflict and rules of engagement"}, {"id": "276be55b-54cf-4ca6-9ce6-bb218ab66fc8", "type": "concept", "title": "Partner performance metrics"}], "description": "Students learn when direct sales should be complemented by partners, resellers, marketplaces, or distributors."}]}, {"id": "329f1941-60c7-4ed8-b6f5-71a771125c7a", "type": "topic", "title": "Forecasting, Pipeline Analytics, and Revenue Operations", "description": "Use pipeline data, sales stages, forecast methods, and revenue operations to guide decisions.", "children": [{"id": "d089ad3d-34b5-4bcd-bfde-a3012e8c790d", "type": "subtopic", "title": "Sales forecasting methods", "children": [{"id": "6fab9b50-46fa-4079-b76e-841ef6f52d0e", "type": "concept", "title": "Rep commit, manager judgment, stage-weighted, and model-based forecasts"}, {"id": "e512b804-cece-4f0a-8ae7-c65f77399260", "type": "concept", "title": "Forecast categories and confidence levels"}, {"id": "e8d39944-a9e2-4a7b-9128-2d1b2856582d", "type": "concept", "title": "Seasonality and sales cycle length"}, {"id": "46040fdc-6d29-42e2-8c3d-43821bbc1871", "type": "concept", "title": "Forecast bias and inspection"}], "description": "Forecasting turns pipeline uncertainty into managerial judgment. Students learn common approaches and failure modes."}, {"id": "08c1a8f1-3c57-4125-88a6-e46da7f9a0f8", "type": "subtopic", "title": "Pipeline analytics", "children": [{"id": "29e0c1d9-5ca9-427a-8cdf-5